//! S04 composite-coordinate battery: the `reader_composite` surface over the
//! pinned mixed WordML fixture.
//!
//! The addresses below are a **handwritten oracle** derived from
//! `fixtures/reader/mixed-wordml.xml` (never generated by the code under test).
//! The fixture is pinned by sha256. A construction that crosses several
//! fragments or a derived separator must be addressed by several ordered units
//! with provenance preserved; malformed addresses must be refused with a typed
//! error.
//!
//! Non-claims: `[bounded]` to the one pinned fixture; no raw decoded legal text
//! is logged; no R1000 closure.

use ln_decode::reader_composite::{
    CompositeAddress, CompositeErrorKind, CompositeUnit, resolve_composite,
};
use ln_decode::reader_contract::{ReaderDerivedKind, ReaderViewKind};
use ln_decode::reader_projection::{ReaderProjection, SegmentId, ViewId, build_projection};
use ln_decode::reader_reading_order::ReadingOrderIndex;
use ln_decode::source_package::{Limits, Record, TextSlot, capture};

const XML: &str = include_str!("fixtures/reader/mixed-wordml.xml");
const FIXTURE_SHA256: &str = "d2fc1cd17f0697f575e94f09d83da5027d73afd37c700772eafa4c4a4fbc76db";

fn fixture() -> (Vec<Record>, ReaderProjection) {
    let package = capture(XML.as_bytes(), &Limits::default()).expect("fixture must capture");
    assert_eq!(
        package.manifest().source.sha256,
        FIXTURE_SHA256,
        "fixture content changed; re-pin FIXTURE_SHA256 and the handwritten oracle"
    );
    let records = package.records().to_vec();
    let projection = build_projection(&records).expect("projection must build");
    (records, projection)
}

fn view_id(projection: &ReaderProjection, kind: ReaderViewKind, element_ref: &str) -> ViewId {
    projection
        .views
        .iter()
        .find(|view| view.kind == kind && view.element_ref.as_str() == element_ref)
        .unwrap_or_else(|| panic!("view {kind:?} {element_ref} missing"))
        .id
        .clone()
}

fn address(view: &ViewId, output_start: usize, output_end: usize) -> CompositeAddress {
    CompositeAddress {
        view: view.clone(),
        output_start,
        output_end,
    }
}

fn source(unit: &CompositeUnit) -> (&str, TextSlot, usize, usize, &str, usize, &SegmentId) {
    match unit {
        CompositeUnit::Source {
            segment,
            fragment_ref,
            slot,
            span,
            element_ref,
            source_pos,
        } => (
            fragment_ref.as_str(),
            *slot,
            span.start,
            span.end,
            element_ref.as_str(),
            *source_pos,
            segment,
        ),
        other => panic!("expected a source unit, got {other:?}"),
    }
}

fn derived(unit: &CompositeUnit) -> (ReaderDerivedKind, &str, usize, &SegmentId) {
    match unit {
        CompositeUnit::Derived {
            segment,
            kind,
            element_ref,
            source_pos,
        } => (*kind, element_ref.as_str(), *source_pos, segment),
        other => panic!("expected a derived unit, got {other:?}"),
    }
}

#[test]
fn multi_run_construction_is_addressed_compositely() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");
    let e5 = view_id(&projection, ReaderViewKind::Paragraph, "e5");

    // "Beta\tPAGE": t1 "Beta" | derived tab | t2 "PAGE".
    let range = resolve_composite(&projection, &index, &records, &address(&e5, 0, 9))
        .expect("full range resolves");
    assert_eq!(range.view, e5);
    assert_eq!((range.output_start, range.output_end), (0, 9));
    assert_eq!(range.units.len(), 3, "t1 + derived tab + t2");

    let (frag, slot, start, end, element, pos, seg) = source(&range.units[0]);
    assert_eq!((frag, start, end), ("t1", 0, 4));
    assert_eq!(slot, TextSlot::Text);
    assert_eq!(seg.as_str(), index.reading_order(&e5).unwrap()[0].as_str());
    let declared = projection
        .segments
        .iter()
        .find(|segment| segment.id.as_str() == seg.as_str())
        .expect("segment exists");
    assert_eq!(element, declared.element_ref.as_str(), "element provenance");
    assert_eq!(pos, declared.source_pos, "source_pos provenance");

    let (kind, _, _, _) = derived(&range.units[1]);
    assert_eq!(kind, ReaderDerivedKind::Tab);

    let (frag, _, start, end, _, _, _) = source(&range.units[2]);
    assert_eq!((frag, start, end), ("t2", 0, 4));

    // A sub-range spanning the derived separator keeps the same unit shape with
    // narrowed source spans and preserved provenance.
    let range = resolve_composite(&projection, &index, &records, &address(&e5, 2, 7))
        .expect("sub-range resolves");
    assert_eq!(range.units.len(), 3);
    let (frag, _, start, end, element, pos, seg) = source(&range.units[0]);
    assert_eq!((frag, start, end), ("t1", 2, 4));
    assert_eq!(element, declared.element_ref.as_str());
    assert_eq!(pos, declared.source_pos);
    assert_eq!(seg.as_str(), index.reading_order(&e5).unwrap()[0].as_str());
    let (kind, _, _, _) = derived(&range.units[1]);
    assert_eq!(kind, ReaderDerivedKind::Tab);
    let (frag, _, start, end, _, _, _) = source(&range.units[2]);
    assert_eq!((frag, start, end), ("t2", 0, 2));
}

#[test]
fn address_across_segment_boundary_yields_two_source_units() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");
    let e24 = view_id(&projection, ReaderViewKind::Paragraph, "e24");

    // "ZetaEta": t7 (0..4) then t8 (4..7). [2, 5) crosses the boundary.
    let range = resolve_composite(&projection, &index, &records, &address(&e24, 2, 5))
        .expect("cross-boundary range resolves");
    assert_eq!(range.units.len(), 2, "two adjacent source fragments");
    let (frag, _, start, end, _, _, _) = source(&range.units[0]);
    assert_eq!((frag, start, end), ("t7", 2, 4));
    let (frag, _, start, end, _, _, _) = source(&range.units[1]);
    assert_eq!((frag, start, end), ("t8", 0, 1));
}

#[test]
fn leading_derived_controls_are_ordered_units() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");
    let e19 = view_id(&projection, ReaderViewKind::Paragraph, "e19");

    // "\n\nEpsilon": line_break | page_break | t6.
    let range = resolve_composite(&projection, &index, &records, &address(&e19, 0, 9))
        .expect("range resolves");
    assert_eq!(range.units.len(), 3);
    let (kind, _, _, _) = derived(&range.units[0]);
    assert_eq!(kind, ReaderDerivedKind::LineBreak);
    let (kind, _, _, _) = derived(&range.units[1]);
    assert_eq!(kind, ReaderDerivedKind::PageBreak);
    let (frag, _, start, end, _, _, _) = source(&range.units[2]);
    assert_eq!((frag, start, end), ("t6", 0, 7));
}

#[test]
fn span_end_inside_multibyte_char_is_refused() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");
    let e38 = view_id(&projection, ReaderViewKind::Paragraph, "e38");

    // "NBSP:\u{a0}Mu": the NBSP occupies bytes 5..7, so ending at 6 lands inside
    // a two-byte code point.
    let error = resolve_composite(&projection, &index, &records, &address(&e38, 0, 6))
        .expect_err("must refuse a mid-codepoint span");
    assert_eq!(error.kind(), CompositeErrorKind::NotCharBoundary);

    // The same range ending on the code point boundary resolves cleanly.
    let range = resolve_composite(&projection, &index, &records, &address(&e38, 0, 7))
        .expect("boundary-aligned range resolves");
    let (frag, _, start, end, _, _, _) = source(&range.units[0]);
    assert_eq!((frag, start, end), ("t13", 0, 7));
}

#[test]
fn malformed_addresses_are_typed_refusals() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");
    let e5 = view_id(&projection, ReaderViewKind::Paragraph, "e5");

    // Past the view output length.
    let error = resolve_composite(&projection, &index, &records, &address(&e5, 0, 10))
        .expect_err("end past output is refused");
    assert_eq!(error.kind(), CompositeErrorKind::OutOfBounds);

    // Empty / inverted interval.
    let error = resolve_composite(&projection, &index, &records, &address(&e5, 5, 5))
        .expect_err("empty interval is refused");
    assert_eq!(error.kind(), CompositeErrorKind::EmptyOrInverted);
    let error = resolve_composite(&projection, &index, &records, &address(&e5, 7, 3))
        .expect_err("inverted interval is refused");
    assert_eq!(error.kind(), CompositeErrorKind::EmptyOrInverted);

    // A fabricated view id.
    let fabricated = ViewId::from("e-does-not-exist");
    let error = resolve_composite(&projection, &index, &records, &address(&fabricated, 0, 1))
        .expect_err("unknown view is refused");
    assert_eq!(error.kind(), CompositeErrorKind::UnknownView);

    // A navigation view.
    let navigation = projection
        .views
        .iter()
        .find(|view| view.kind.is_navigation())
        .expect("fixture carries a navigation view")
        .id
        .clone();
    let error = resolve_composite(&projection, &index, &records, &address(&navigation, 0, 1))
        .expect_err("navigation view is refused");
    assert_eq!(error.kind(), CompositeErrorKind::NotPrimaryView);
}

#[test]
fn derivation_is_read_only_and_round_trips() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");
    let e5 = view_id(&projection, ReaderViewKind::Paragraph, "e5");

    let first = resolve_composite(&projection, &index, &records, &address(&e5, 0, 9))
        .expect("range resolves");
    let second = resolve_composite(&projection, &index, &records, &address(&e5, 0, 9))
        .expect("range resolves again");
    assert_eq!(
        first.units, second.units,
        "resolution is deterministic/read-only"
    );
    assert_eq!(
        first.to_address(),
        address(&e5, 0, 9),
        "address round-trips"
    );

    // Derived units structurally cannot carry a fragment or span: this match
    // enumerates only the two provenance fields.
    match &first.units[1] {
        CompositeUnit::Derived {
            segment,
            kind,
            element_ref,
            source_pos,
        } => {
            assert_eq!(*kind, ReaderDerivedKind::Tab);
            let declared = projection
                .segments
                .iter()
                .find(|candidate| candidate.id.as_str() == segment.as_str())
                .expect("derived segment exists");
            assert_eq!(element_ref.as_str(), declared.element_ref.as_str());
            assert_eq!(*source_pos, declared.source_pos);
        }
        other => panic!("expected a derived unit, got {other:?}"),
    }
}
